from auth import require_login

ROUTES = {}


def route(path):
    def register(handler):
        ROUTES[path] = handler
        return handler
    return register


@route('/login')
def login(request):
    return {'token': request.issue_token()}


@route('/orders')
@require_login
def orders(request):
    return request.db.orders_for(request.user)


@route('/admin/export')
def export_all(request):
    return request.db.all_customers()

